async function fetchPage(cursor) {
  const start = cursor ? Number(cursor) : 0;
  const total = 437;
  const items = [];
  for (let i = start; i < Math.min(start + 100, total); i++) items.push({ id: i, name: `user ${i}`, email: i === 42 ? "" : `u${i}@example.com` });
  return { items, next: start + 100 < total ? String(start + 100) : null };
}

